// app/api/website-builder/themes/[installId]/sections/route.ts
import { websiteInstallCaller } from "@/lib/team/website";

// lib/storelib-theme/types.ts
var SECTION_SCHEMA_VERSION = 1;
var MAX_BLOCK_DEPTH = 8;
var LIMITS = {
  /** Bytes. The whole package. */
  packageBytes: 50 * 1024 * 1024,
  /** Bytes. One asset. */
  assetBytes: 15 * 1024 * 1024,
  /** Bytes. One source file, including a section such as sections/flux_header.storelib. */
  sourceBytes: 5e3 * 1024,
  /** Bytes. A section's compiled script. */
  scriptBytes: 64 * 1024,
  /** Bytes. A section's CSS. Same ceiling as a source file, so a large generated stylesheet still imports. */
  cssBytes: 5e3 * 1024,
  filesPerPackage: 2e3,
  sectionsPerTemplate: 60,
  blocksPerSection: 50,
  settingsPerSchema: 120
};

// lib/website-builder/block-tree.ts
function countAll(list) {
  let n = 0;
  for (const b of list ?? []) n += 1 + countAll(b.blocks);
  return n;
}
function depthOf(list) {
  if (!list?.length) return 0;
  return 1 + Math.max(...list.map((b) => depthOf(b.blocks)));
}
function blockTreeProblem(section) {
  const total = countAll(section.blocks);
  const label = section.name || section.type;
  if (total > LIMITS.blocksPerSection) return `A section holds ${LIMITS.blocksPerSection} blocks. "${label}" has ${total}.`;
  if (depthOf(section.blocks) > MAX_BLOCK_DEPTH) return `Blocks nest ${MAX_BLOCK_DEPTH} deep at most. "${label}" goes deeper.`;
  return null;
}

// lib/website-builder/block-tree-schema.ts
import { z } from "zod";
var BlockInstanceSchema = /* @__PURE__ */ z.lazy(
  () => z.object({
    id: z.string().min(1).max(128),
    type: z.string().min(1).max(64),
    settings: z.record(z.unknown()),
    hidden: z.boolean().optional(),
    static: z.boolean().optional(),
    blocks: z.array(BlockInstanceSchema).max(LIMITS.blocksPerSection).optional()
  })
);

